    else
        std::sprintf(buf, "%04d", v);
    return CCharString(buf);
}
static int StringValue(const CCharString& s, char prefix)
{
    if (s.PStringData == 0)
        return -1;
    if (prefix)
        return s.PStringData[0] == prefix ? std::atoi(s.PStringData + 1) : -1000;
    return std::atoi(s.PStringData);
