    for (int i = 0; i < n; ++i)
        seen[i] = 0;
    for (int i = 0; i < n; ++i) {
        int t = TagOf(a[i]);
        if (t < 0 || t >= n || seen[t] || KeyOf(a[i]) != keys[t] || !PayloadOk(a[i]))
