static bool TestFunction()                              // __unguarded_linear_insert: shift greater keys up, insert after equals
{
    static const int keys[9] = { 2, 5, 5, 9, 12, 12, 12, 20, 12 };
    static const int want[9] = { 0, 1, 2, 3, 4, 5, 6, 8, 7 };
    static const int keys2[5] = { 2, 4, 6, 8, 2 };
    static const int want2[5] = { 0, 4, 1, 2, 3 };
